from collections import Counter

class Solution:
    def quotaWindow(self, text: str, quota: str) -> str:
        if not quota:
            return ""
        need = Counter(quota)
        missing, left = len(quota), 0
        best_start, best_length = 0, len(text) + 1
        for right, char in enumerate(text):
            if char in need:
                if need[char] > 0:
                    missing -= 1
                need[char] -= 1
            while missing == 0:
                length = right - left + 1
                if length < best_length:
                    best_start, best_length = left, length
                char = text[left]
                if char in need:
                    need[char] += 1
                    if need[char] > 0:
                        missing += 1
                left += 1
        return "" if best_length > len(text) else text[best_start:best_start + best_length]

class Solution  {
    public String quotaWindow(String text,String quota) {
        int[] chars=text.codePoints().toArray(), requested=quota.codePoints().toArray();
        if(requested.length==0)return "";
        HashMap<Integer,Integer> need=new HashMap<>();
        for(int c:requested)need.put(c,need.getOrDefault(c,0)+1);
        int missing=requested.length,left=0,start=0,best=Integer.MAX_VALUE;
        for(int right=0;right<chars.length;right++) {
            int c=chars[right];
            if(need.getOrDefault(c,0)>0)missing--;
            need.put(c,need.getOrDefault(c,0)-1);
            while(missing==0) {
                if(right-left+1<best) {
                    best=right-left+1;
                    start=left;
                }
                int old=chars[left++];
                need.put(old,need.getOrDefault(old,0)+1);
                if(need.get(old)>0)missing++;
            }
        }
        return best==Integer.MAX_VALUE?"":new String(chars,start,best);
    }
}

class Solution  {
    quotaWindow(text:string,quota:string):string {
        if(!quota)return '';
        const chars=Array.from(text),need=new Map<string,number>();
        for(const c of quota)need.set(c,(need.get(c)??0)+1);
        let missing=Array.from(quota).length,left=0,start=0,best=Infinity;
        for(let right=0;right<chars.length;right++) {
            const c=chars[right];
            if((need.get(c)??0)>0)missing--;
            need.set(c,(need.get(c)??0)-1);
            while(missing===0) {
                if(right-left+1<best) {
                    best=right-left+1;
                    start=left;
                }
                const old=chars[left++];
                need.set(old,(need.get(old)??0)+1);
                if(need.get(old)!>0)missing++;
            }
        }
        return best===Infinity?'':chars.slice(start,start+best).join('');
    }
}

let scalars text =
    let rec loop index acc =
        if index=String.length text then Array.of_list (List.rev acc) else
        let byte=Char.code text.[index] in
        let width=if byte<128 then 1 else if byte<224 then 2 else if byte<240 then 3 else 4 in
        loop (index+width) (String.sub text index width::acc)
    in loop 0 []

let quotaWindow text quota =
    let chars=scalars text and requested=scalars quota in
    if Array.length requested=0 then "" else
    let need=Hashtbl.create 32 in
    let get c=Option.value (Hashtbl.find_opt need c) ~default:0 in
    Array.iter (fun c -> Hashtbl.replace need c (get c+1)) requested;
    let missing=ref (Array.length requested) and left=ref 0 and start=ref 0 and best=ref max_int in
    Array.iteri (fun right c ->
        if get c>0 then decr missing;
        Hashtbl.replace need c (get c-1);
        while !missing=0 do
            if right- !left+1< !best then (best:=right- !left+1;start:= !left);
            let old=chars.(!left) in
            Hashtbl.replace need old (get old+1);
            if get old>0 then incr missing;
            incr left
        done
    ) chars;
    if !best=max_int then "" else String.concat "" (Array.to_list (Array.sub chars !start !best))
